trait Ranked {
    fn rank(&self) -> i64;
}

impl Ranked for i32 {
    fn rank(&self) -> i64 { i64::from(*self) }
}

impl Ranked for u32 {
    fn rank(&self) -> i64 { i64::from(*self) }
}

fn largest<T: Ranked + Copy>(values: &[T]) -> Option<T> {
    let mut largest = *values.first()?;
    for value in values.iter().copied().skip(1) {
        if value.rank() > largest.rank() { largest = value; }
    }
    Some(largest)
}
